yaml_template:
name: stage-review-MEISGN Company Policy - Data Exfiltration Attempts
visualization:
  options:
    columns:
    - fieldName: '@timestamp'
      format: datetime
      type: field
      width: 200
    - groupByPrefix: false
      header: Field List
      type: fieldList
    newestAtBottom: true
    showOnlyFirstLine: false
  type: list-view
labels:
- daac
- bk1191
- pdl
$schema: https://schemas.humio.com/query/v0.6.0
timeInterval:
  isLive: false
  start: 15m
queryString: |-
  // RULE NAME: MEISGN Company Policy - Data Exfiltration Attempts

  // ============================================================
  // SECTION 1: Log Source Fields (tagged fields for filtering - improves performance)
  // ============================================================
  | #Vendor = octan
  | lab.source = "<studentid>-octan"

  // ============================================================
  // SECTION 2: CPS Category Fields (tagged fields for filtering - improves performance)
  // ============================================================
  | #event.dataset = firewall.network
  | #event.kind = alert
  | #event.module = firewall
  | #event.outcome = failure
  | event.category[0] = network
  | event.reason = "Data exfiltration attempt detected"

  // ============================================================
  // SECTION 3: Query Target (specific logic core to use case)
  // ============================================================
  // Filter for VIP users only
  | user.id = "jsmith" OR user.id = "janedoe"

  // Filter for Data exfiltration message
  | message = "Data exfiltration attempt detected"

  // ============================================================
  // SECTION 4: Aggregation / Grouping (if needed)
  // ============================================================
  | groupBy([user.id], function=[
    count(as=total_exfil_attempts),
    collect(rule.name, Vendor.device_name, source.port, destination.port, limit=10)
  ])

  // ============================================================
  // SECTION 5: Exclusions + Threshold Filtering
  // ============================================================
  | "total_exfil_attempts" > 3

  // ============================================================
  // SECTION 6: Rule Notes
  // ============================================================
